const body = $json.body || $json;

const question =
  body.message ||
  body.question ||
  body.chatInput ||
  body.prompt ||
  "";

const sessionId = body.sessionId || "default-session";

if (!question || !question.trim()) {
  return [
    {
      json: {
        error: true,
        question: "",
        sessionId,
        answer: "Please provide a question.",
        specialistResults: [],
        evidenceGraph: {
          nodes: [],
          edges: [],
        },
      },
    },
  ];
}

return [
  {
    json: {
      error: false,
      question: question.trim(),
      sessionId,
      timestamp: new Date().toISOString(),
    },
  },
];

const question = $json.question || "";
const q = question.toLowerCase();

const selectedAgents = [];

const procurementKeywords = [
  "supplier",
  "suppliers",
  "purchase order",
  "po",
  "procurement",
  "sourcing",
  "vendor",
  "lead time",
  "material",
  "materials"
];

const riskKeywords = [
  "risk",
  "risky",
  "delay",
  "delayed",
  "bottleneck",
  "critical",
  "failure",
  "incident",
  "audit",
  "maintenance"
];

const logisticsKeywords = [
  "shipment",
  "shipping",
  "transport",
  "route",
  "delivery",
  "freight",
  "warehouse",
  "location",
  "logistics"
];

const sustainabilityKeywords = [
  "carbon",
  "emission",
  "emissions",
  "co2",
  "recycling",
  "waste",
  "sustainability",
  "environment",
  "environmental"
];

const qualityKeywords = [
  "quality",
  "test",
  "testing",
  "defect",
  "inspection",
  "audit",
  "report"
];

const runProcurement = procurementKeywords.some(k => q.includes(k));
const runRisk = riskKeywords.some(k => q.includes(k));
const runLogistics = logisticsKeywords.some(k => q.includes(k));
const runSustainability = sustainabilityKeywords.some(k => q.includes(k));
const runQuality = qualityKeywords.some(k => q.includes(k));

if (runProcurement) selectedAgents.push("procurement_specialist");
if (runRisk) selectedAgents.push("risk_analyst");
if (runLogistics) selectedAgents.push("logistics_specialist");
if (runSustainability) selectedAgents.push("sustainability_analyst");
if (runQuality) selectedAgents.push("quality_analyst");

// fallback: if nothing matches, run manager with general context later
if (selectedAgents.length === 0) {
  selectedAgents.push("procurement_specialist", "risk_analyst");
}

return [
  {
    json: {
      ...$json,
      selectedAgents,
      runProcurement,
      runRisk,
      runLogistics,
      runSustainability,
      runQuality,
    },
  },
];

const question = $("Normalize Chat Input").first().json.question || "";
const sessionId = $("Normalize Chat Input").first().json.sessionId || "default-session";
const selectedAgents = $("Route Question").first().json.selectedAgents || [];
const sourceChunks = $("Parse RAG Chunks").first().json.sourceChunks || [];

function getNodeJson(nodeName) {
  try {
    return $(nodeName).first().json;
  } catch (e) {
    return {
      agent: nodeName,
      status: "error",
      answer: `Could not read output from ${nodeName}`,
      keyFindings: [],
      recommendations: [],
      confidence: "low",
      error: e.message,
    };
  }
}

const procurement = getNodeJson("Run Procurement Specialist");
const risk = getNodeJson("Run Risk Analyst");
const logistics = getNodeJson("Run Logistics Specialist");
const sustainability = getNodeJson("Run Sustainability Analyst");
const quality = getNodeJson("Run Quality Analyst");

const allSpecialistResults = [
  procurement,
  risk,
  logistics,
  sustainability,
  quality,
].filter(Boolean);

const specialistResults = allSpecialistResults.filter(
  (result) => result.status !== "skipped"
);

const toolsUsed = [];
if (sourceChunks.length > 0) {
  toolsUsed.push({
    id: "vector_search",
    name: "Vector Search (Unstructured RAG)",
    status: "success",
    inputSummary: question,
    outputSummary: `Found ${sourceChunks.length} matching unstructured documents.`
  });
}

const CYPHER_TEMPLATES = {
  procurement_specialist: `MATCH (a:Actor)
WHERE coalesce(a.is_canonical_actor, false) = true AND (toLower(coalesce(a.actor_role, "")) IN ["supplier", "manufacturer", "vendor"] OR toLower(coalesce(a.display_name, a.actor_name, a.name, "")) CONTAINS "supplier" OR toLower(coalesce(a.display_name, a.actor_name, a.name, "")) CONTAINS "materials" OR toLower(coalesce(a.display_name, a.actor_name, a.name, "")) CONTAINS "manufacturing" OR toLower(coalesce(a.display_name, a.actor_name, a.name, "")) CONTAINS "vendor" OR EXISTS { MATCH (a)-[:SUPPLIES]-() })
OPTIONAL MATCH (a)-[r]-(connected)
RETURN coalesce(a.canonical_id, a.id, a.actor_id) AS supplier_id, coalesce(a.display_name, a.actor_name, a.name) AS supplier_name, a.region AS region, a.actor_origin AS actor_origin, a.actor_role AS actor_role, labels(connected) AS connected_labels, coalesce(connected.canonical_id, connected.id, connected.display_name, connected.actor_name, connected.name, connected.unit_id, connected.process_id, connected.material_id, connected.location_name) AS connected_entity, type(r) AS relationship, properties(connected) AS connected_properties
ORDER BY supplier_id LIMIT 100`,

  risk_analyst: `MATCH (n)
WHERE n:Risk OR n:IncidentReport OR n:AuditFinding OR n:MaintenanceEvent OR n:TestReport
OPTIONAL MATCH (n)-[r]-(connected)
RETURN coalesce(n.canonical_id, n.id, n.risk_id, n.incident_id, n.audit_id, n.test_report_id, n.maintenance_id) AS item_id, labels(n)[0] AS item_type, coalesce(n.name, n.risk_name, n.description, n.finding, n.incident_description, n.event_type, n.status, n.id) AS item_name, properties(n) AS properties, type(r) AS relationship, labels(connected) AS connected_labels, coalesce(connected.canonical_id, connected.id, connected.actor_name, connected.name, connected.unit_id, connected.process_id, connected.material_name, connected.location_name) AS connected_entity
LIMIT 100`,

  logistics_specialist: `MATCH (n)
WHERE n:Location OR n:Transport OR (n:Actor AND (toLower(coalesce(n.actor_name, n.name, "")) CONTAINS "logistics" OR toLower(coalesce(n.actor_name, n.name, "")) CONTAINS "freight" OR toLower(coalesce(n.actor_name, n.name, "")) CONTAINS "transport" OR toLower(coalesce(n.actor_name, n.name, "")) CONTAINS "shipping" OR toLower(coalesce(n.actor_name, n.name, "")) CONTAINS "carrier"))
OPTIONAL MATCH (n)-[r]-(connected)
RETURN coalesce(n.canonical_id, n.id, n.transport_id, n.location_code, n.actor_id, n.unit_id) AS item_id, labels(n)[0] AS item_type, coalesce(n.location_name, n.actor_name, n.name, n.route_from, n.route_to, n.country, n.id) AS item_name, properties(n) AS properties, type(r) AS relationship, labels(connected) AS connected_labels, coalesce(connected.canonical_id, connected.id, connected.unit_id, connected.serial_number, connected.actor_name, connected.name, connected.process_id, connected.process_name, connected.material_name, connected.location_name) AS connected_entity
LIMIT 100`,

  sustainability_analyst: `MATCH (n)
WHERE n:Material OR (n:Actor AND (toLower(coalesce(n.actor_name, n.name, "")) CONTAINS "recycling" OR toLower(coalesce(n.actor_name, n.name, "")) CONTAINS "recovery" OR toLower(coalesce(n.actor_name, n.name, "")) CONTAINS "waste" OR toLower(coalesce(n.actor_name, n.name, "")) CONTAINS "environment" OR toLower(coalesce(n.actor_name, n.name, "")) CONTAINS "sustainability")) OR any(k IN keys(n) WHERE toLower(k) CONTAINS "carbon" OR toLower(k) CONTAINS "co2" OR toLower(k) CONTAINS "emission" OR toLower(k) CONTAINS "recycling" OR toLower(k) CONTAINS "recycled" OR toLower(k) CONTAINS "waste" OR toLower(k) CONTAINS "environment" OR toLower(k) CONTAINS "sustainability")
OPTIONAL MATCH (n)-[r]-(connected)
RETURN coalesce(n.canonical_id, n.id, n.material_id, n.actor_id, n.unit_id, n.process_id, n.location_code) AS item_id, labels(n)[0] AS item_type, coalesce(n.material_name, n.actor_name, n.name, n.process_name, n.location_name, n.serial_number, n.id) AS item_name, properties(n) AS properties, type(r) AS relationship, labels(connected) AS connected_labels, coalesce(connected.canonical_id, connected.id, connected.actor_name, connected.name, connected.unit_id, connected.process_id, connected.process_name, connected.material_name, connected.location_name) AS connected_entity
LIMIT 100`,

  quality_analyst: `MATCH (n)
WHERE n:TestReport OR n:AuditFinding OR n:IncidentReport OR n:MaintenanceEvent OR any(k IN keys(n) WHERE toLower(k) CONTAINS "quality" OR toLower(k) CONTAINS "test" OR toLower(k) CONTAINS "defect" OR toLower(k) CONTAINS "failure" OR toLower(k) CONTAINS "inspection" OR toLower(k) CONTAINS "audit" OR toLower(k) CONTAINS "result")
OPTIONAL MATCH (n)-[r]-(connected)
RETURN coalesce(n.canonical_id, n.id, n.test_report_id, n.audit_id, n.incident_id, n.maintenance_id) AS item_id, labels(n)[0] AS item_type, coalesce(n.name, n.description, n.finding, n.status, n.result, n.event_type, n.incident_description, n.id) AS item_name, properties(n) AS properties, type(r) AS relationship, labels(connected) AS connected_labels, coalesce(connected.canonical_id, connected.id, connected.actor_name, connected.name, connected.unit_id, connected.process_id, connected.process_name, connected.material_name, connected.location_name) AS connected_entity
LIMIT 100`
};

const cypherQueries = [];
specialistResults.forEach((spec) => {
  if (spec.agent && CYPHER_TEMPLATES[spec.agent]) {
    cypherQueries.push({ query: CYPHER_TEMPLATES[spec.agent] });
  }
});

const allRecords = [];
specialistResults.forEach((spec) => {
  if (spec.evidence && typeof spec.evidence === "object") {
    Object.values(spec.evidence).forEach((val) => {
      if (Array.isArray(val)) {
        allRecords.push(...val);
      }
    });
  }
});

let tableColumns = [];
let tableRows = [];
if (allRecords.length > 0) {
  const cols = new Set();
  allRecords.forEach((row) => {
    Object.keys(row).forEach((k) => cols.add(k));
  });
  tableColumns = Array.from(cols);
  tableRows = allRecords;
}

return [
  {
    json: {
      question,
      sessionId,
      selectedAgents,
      specialistResults,
      allSpecialistResults,
      sourceChunks,
      toolsUsed,
      cypherQueries,
      tableColumns,
      tableRows,
      embeddingMode: $("GetEmbeddingAPI").first().json.embeddingMode || "fallback",
      timestamp: new Date().toISOString(),
    },
  },
];

const embedding = $json.embedding;
const embeddingMode = $json.embeddingMode || "fallback";

const chunkQuery = `
  CALL db.index.vector.queryNodes('chunk_embeddings', 3, $embedding)
  YIELD node, score
  RETURN node.file_name AS filename, node.index AS chunk_index, node.text AS content, score
`;

return [{
  json: {
    body: {
      query: chunkQuery,
      params: {
        embedding,
        limit: 3
      }
    },
    embeddingMode
  }
}];

const results = $json.results || [];
const sourceChunks = results.map((r, idx) => ({
  id: `chunk_${idx}`,
  documentName: r.filename || "Unknown Document",
  text: r.content || ""
}));

let original = {};
try {
  original = $("Normalize Chat Input").first().json;
} catch (e) {
  original = {};
}

return [{
  json: {
    ...original,
    sourceChunks
  }
}];
